<?php
// Protected profile page: displays customer details and supports selected demo account-setting actions.
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_login(); require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/helpers.php';
$pdo = db(); $userId = $_SESSION['user_id']; $errors = []; $message = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf()) { $errors['general'] = 'Your form session has expired. Please try again.'; }
    elseif (($_POST['profile_action'] ?? '') === 'details') {
        $email = trim((string)($_POST['email'] ?? '')); $phone = trim((string)($_POST['phone'] ?? ''));
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) $errors['email'] = 'Enter a valid email address.';
        if (strlen(preg_replace('/[^0-9+]/', '', $phone)) < 7) $errors['phone'] = 'Enter a valid telephone number.';
        if (!$errors) { $dup=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>?');$dup->execute([$email,$userId]); if($dup->fetch()) $errors['email']='That email address is already in use.'; else { $update=$pdo->prepare('UPDATE users SET email=?, phone=? WHERE id=?');$update->execute([$email,$phone,$userId]);$message='Your profile details have been updated.'; } }
    } elseif (($_POST['profile_action'] ?? '') === 'password') {
        $current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
        $record=$pdo->prepare('SELECT password FROM users WHERE id=?');$record->execute([$userId]);$hash=(string)$record->fetchColumn();
        if(!password_verify($current,$hash)) $errors['password']='Your current password is not correct.'; elseif(strlen($new)<8) $errors['password']='Use at least 8 characters for your new password.'; elseif($new!==$confirm) $errors['password']='New passwords do not match.'; else { $update=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$update->execute([password_hash($new,PASSWORD_DEFAULT),$userId]);$message='Your password has been changed.'; }
    }
}
$userStmt=$pdo->prepare('SELECT * FROM users WHERE id=?');$userStmt->execute([$userId]);$user=$userStmt->fetch();$accountStmt=$pdo->prepare('SELECT account_type FROM accounts WHERE user_id=? ORDER BY id LIMIT 1');$accountStmt->execute([$userId]);$accountType=(string)($accountStmt->fetchColumn()?:'Customer');
$pageTitle='Profile & Settings';$portal=true;require __DIR__.'/includes/header.php';
?>
<section class="portal-shell"><div class="portal-welcome"><div><p class="eyebrow">Profile &amp; settings</p><h1>Keep your details up to date.</h1><p>Manage the information attached to your DDB demonstration account.</p></div><p class="demo-badge">Logged in</p></div><?php if($message):?><div class="notice notice-success" role="status"><?=e($message)?></div><?php endif;?><?php if(isset($errors['general'])):?><div class="form-alert" role="alert"><?=e($errors['general'])?></div><?php endif;?><div class="profile-layout"><section class="profile-card profile-summary"><span class="profile-avatar" aria-hidden="true"><?=e(strtoupper(substr($user['first_name'],0,1).substr($user['last_name'],0,1)))?></span><h2><?=e($user['first_name'].' '.$user['last_name'])?></h2><p><?=e($user['email'])?></p><dl><div><dt>Account type</dt><dd><?=e($accountType)?></dd></div><div><dt>Member since</dt><dd><?=e(date_label($user['created_at']))?></dd></div><div><dt>Login status</dt><dd><span class="status-active"><i></i>Active</span></dd></div></dl><a class="button button-outline button-full" href="logout.php">Log out</a></section><div class="profile-forms"><section class="settings-card"><p class="eyebrow">Contact details</p><h2>Edit selected profile information</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="profile_action" value="details"><div class="form-grid two-columns"><div><label for="email">Email address</label><input id="email" name="email" type="email" value="<?=e($user['email'])?>" required><?php if(isset($errors['email'])):?><p class="field-error"><?=e($errors['email'])?></p><?php endif;?></div><div><label for="phone">Telephone number</label><input id="phone" name="phone" value="<?=e($user['phone'])?>" required><?php if(isset($errors['phone'])):?><p class="field-error"><?=e($errors['phone'])?></p><?php endif;?></div></div><button class="button button-small" type="submit">Save details</button></form></section><section class="settings-card"><p class="eyebrow">Security</p><h2>Change password</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="profile_action" value="password"><div class="form-grid three-columns"><div><label for="current_password">Current password</label><input id="current_password" type="password" name="current_password" autocomplete="current-password" required></div><div><label for="new_password">New password</label><input id="new_password" type="password" name="new_password" autocomplete="new-password" minlength="8" required></div><div><label for="confirm_password">Confirm new password</label><input id="confirm_password" type="password" name="confirm_password" autocomplete="new-password" minlength="8" required></div></div><?php if(isset($errors['password'])):?><p class="field-error"><?=e($errors['password'])?></p><?php endif;?><button class="button button-small" type="submit">Update password</button></form></section></div></div></section>
